package com.bank.core;

import java.math.BigDecimal;
import java.util.logging.*;

public class VarargsDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    // Varargs MUST be last; one fixed param 'action' then variable 'details'.
    // Internally compiled as audit(String action, Object[] details).
    static void audit(String action, Object... details) {
        // 'details' is NEVER null — an empty array (length 0) if none passed.
        StringBuilder sb = new StringBuilder(action);
        for (Object d : details) sb.append(" | ").append(d);
        log.info(() -> "AUDIT: " + sb + "  (details count=" + details.length + ")");
    }

    // Varargs of BigDecimal: sum any number of transaction amounts.
    static BigDecimal sum(BigDecimal... amounts) {
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal a : amounts) total = total.add(a);
        return total;
    }

    public static void main(String[] args) {
        // 1) Zero varargs → empty array, not null
        audit("LOGIN");
        // 2) Several loose arguments → compiler bundles into Object[]
        audit("TRANSFER", "SAV2001", new BigDecimal("50000.00"), "CUR3001");
        // 3) Passing an explicit array works because the param IS an array
        Object[] preBundled = { "STATEMENT", "SAV2001", "2026-10" };
        audit("REPORT", preBundled);

        // 4) Sum with varying counts
        BigDecimal one   = sum(new BigDecimal("50000.00"));
        BigDecimal three = sum(new BigDecimal("50000.00"),
                               new BigDecimal("12000.00"),
                               new BigDecimal("8000.00"));
        BigDecimal none  = sum(); // empty array → zero
        log.info(() -> "sum(one)   = " + one);
        log.info(() -> "sum(three) = " + three);
        log.info(() -> "sum()      = " + none + " (empty varargs → ZERO)");

        // 5) Explicit BigDecimal[] also accepted directly
        BigDecimal[] batch = { new BigDecimal("1000"), new BigDecimal("2000") };
        log.info(() -> "sum(array) = " + sum(batch));
    }
}
